function fS(a2H) {
  this.noroom = 0;
  let a2e = 0;
  let a2D = 0;
  if (a2e === 0) {
    let a2l = 0;
    JN(this, "__weapon")[0] = a2H;
    a2D = 0;
    for (; a2D < 48; a2D++) {
      if (gX.weapon[a2D] !== 0) {
        JN(this, "__weapon")[Math.trunc(a2l + 1)] = gX.weapon[a2D];
        a2l++;
      }
    }
    if (a2l >= 48) {
      this.noroom = 1;
    } else {
      for (a2D = 0; a2D < 48; a2D++) {
        if (a2D <= a2l) {
          JN(gX, "weapon")[a2D] = this.__weapon[a2D];
        } else {
          JN(gX, "weapon")[a2D] = 0;
        }
      }
    }
  } else if (gQ(a2e)) {
    this.loop = 1;
    JN(gX, "weapon")[48] = 999;
    for (let a2s = 0; this.loop === 1;) {
      if (++a2s > 5000000) {
        throw new Error("GML loop ran 5000000 times without ending");
      }
      if (gX.weapon[a2D] === 0) {
        JN(gX, "weapon")[a2D] = a2H;
        break;
      }
      if (a2D === 48) {
        this.noroom = 1;
        break;
      }
      a2D += 1;
    }
  }
  ZE(this, q7("scr_weaponinfo_all"));
}
